import{_ as e,o as l,c as r,a3 as o}from"./chunks/framework.Dj4Lt7vj.js";const f=JSON.parse('{"title":"管理知识库","description":"","frontmatter":{"title":"管理知识库"},"headers":[],"relativePath":"workspace/knowledge.md","filePath":"workspace/knowledge.md","lastUpdated":1787948622000}'),i={name:"workspace/knowledge.md"};function t(n,a,s,d,c,h){return l(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="管理知识库" tabindex="-1">管理知识库 <a class="header-anchor" href="#管理知识库" aria-label="Permalink to &quot;管理知识库&quot;">​</a></h1><p>工作台的「知识库」标签页集中管理店铺资料。知识库的概念和结构见<a href="/aicare-docs/knowledge/basics">知识库是什么</a>，这一页只讲工作台里的操作。</p><h2 id="能做什么" tabindex="-1">能做什么 <a class="header-anchor" href="#能做什么" aria-label="Permalink to &quot;能做什么&quot;">​</a></h2><ul><li>查看账号下的所有知识库和每个库的条目。</li><li>新增、编辑、删除问答条目。</li><li>上传文档资料，见<a href="/aicare-docs/knowledge/qa-and-files">录入问答和文档</a>。</li><li>查看商品学习的结果，见<a href="/aicare-docs/knowledge/product-learn">商品学习</a>。</li></ul><h2 id="和「商品信息」标签页的分工" tabindex="-1">和「商品信息」标签页的分工 <a class="header-anchor" href="#和「商品信息」标签页的分工" aria-label="Permalink to &quot;和「商品信息」标签页的分工&quot;">​</a></h2><ul><li><strong>知识库</strong>：放可复用的店铺资料——售后政策、发货说明、常见问答。</li><li><strong>商品信息</strong>：维护具体商品的参数、卖点、尺码和售后说明，按商品组织。</li></ul><p>顾客问「这款鞋偏码吗」，AI 用商品信息回答；问「多久发货」，AI 用知识库回答。</p><h2 id="日常维护建议" tabindex="-1">日常维护建议 <a class="header-anchor" href="#日常维护建议" aria-label="Permalink to &quot;日常维护建议&quot;">​</a></h2><ol><li><strong>每周看一次待办</strong>：AI 发现答不上来的问题会生成知识缺口待办（见<a href="/aicare-docs/client/notify">通知设置</a>的「AI 推送待办信息」），及时补充对应的问答。</li><li><strong>大促前集中更新</strong>：活动规则、发货时效变化先改知识库，再开始接待。</li><li><strong>删掉过期内容</strong>：过期的活动话术要删除或停用，否则 AI 可能拿旧信息回答。</li></ol><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/aicare-docs/knowledge/basics">知识库是什么</a></li><li><a href="/aicare-docs/knowledge/retrieval">AI 如何使用知识库</a></li></ul>',11)])])}const _=e(i,[["render",t]]);export{f as __pageData,_ as default};
